"""Anima WebUI 登录页。"""

LOGIN_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#11101e"><title>Anima · 登录生命控制台</title>
<style>
:root{color-scheme:dark;--bg:#11101e;--panel:#1d182d;--ink:#fff9ef;--muted:#bcaec7;--line:#554363;--lime:#bdf46d;--paper:#fff2d7;--ease:cubic-bezier(.22,1,.36,1)}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:18px;background:radial-gradient(750px 430px at 10% 0,#79517d55,transparent 68%),radial-gradient(650px 400px at 100% 0,#24556b44,transparent 65%),var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;overflow:hidden}body:before{content:"";position:fixed;inset:0;opacity:.25;pointer-events:none;background-image:linear-gradient(#fff08 1px,transparent 1px),linear-gradient(90deg,#fff08 1px,transparent 1px);background-size:32px 32px;mask-image:linear-gradient(transparent,#000 35%,transparent)}.card{position:relative;width:min(450px,100%);padding:clamp(25px,6vw,40px);border:1px solid var(--line);border-radius:26px;background:#1d182df2;box-shadow:12px 14px 0 #090710;animation:enter .55s var(--ease)}.brand{display:flex;gap:14px;align-items:center;margin-bottom:28px}.mark{position:relative;display:grid;place-items:center;width:58px;height:58px;border-radius:20px 20px 20px 6px;background:var(--lime);color:#1c2318;box-shadow:7px 8px 0 #735078;font:900 28px Georgia,serif;transform:rotate(-3deg);animation:float 3.4s ease-in-out infinite}.mark:after{content:"";position:absolute;width:9px;height:9px;border-radius:50%;background:#ff70a2;right:12px;top:18px}.brand b{display:block;font-size:27px;line-height:1}.brand span{color:var(--muted);font-size:12px}h1{margin:0 0 8px;font-size:24px;letter-spacing:-.5px}p{margin:0 0 23px;color:var(--muted)}label{display:block;margin-bottom:7px;font-size:12px;font-weight:750;color:#d8cadd}input{width:100%;border:1px solid #5a4767;border-radius:12px;background:#120f1b;color:var(--ink);padding:12px 13px;outline:0;transition:border-color .2s,box-shadow .2s}input:focus{border-color:#9e7eb0;box-shadow:0 0 0 4px #bdf46d17}button{width:100%;margin-top:13px;border:0;border-radius:12px;background:var(--lime);color:#192216;padding:12px;font-weight:850;cursor:pointer;box-shadow:4px 5px 0 #735078;transition:transform .16s var(--ease),filter .16s}button:hover{transform:translateY(-2px);filter:brightness(1.05)}button:active{transform:translateY(1px);box-shadow:none}button[aria-busy=true]{opacity:.62;cursor:wait}.error{min-height:23px;margin-top:12px;color:#ff9bac;font-weight:700}.safe{margin-top:18px;padding-top:16px;border-top:1px solid #41344c;color:#9f92aa;font-size:11px}.safe b{color:#cfbfd7}@keyframes enter{from{opacity:0;transform:translateY(18px) scale(.98)}to{opacity:1;transform:none}}@keyframes float{50%{transform:translateY(-4px) rotate(-3deg)}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
</style></head><body><main class="card"><div class="brand"><div class="mark">H</div><div><b>Anima</b><span>哈基米生命控制台</span></div></div><h1>欢迎回来，主人</h1><p>输入 WebUI Token，查看她的运行、记忆、能力与待审批工程。</p><form id="loginForm"><label for="token">WebUI Token</label><input id="token" type="password" autocomplete="current-password" spellcheck="false" placeholder="输入你的访问 Token" required><button id="submit" type="submit">进入生命控制台</button><div id="error" class="error" role="alert" aria-live="polite"></div></form><div class="safe"><b>凭据保护：</b>登录后使用 HttpOnly Cookie；高危写操作还会校验 CSRF，不在页面回显任何密钥。<br><a href="/source" style="display:inline-block;margin-top:10px;color:#d8cadd;text-underline-offset:3px">AGPL-3.0-only · 查看当前对应源码</a></div></main>
<script>
var form=document.getElementById('loginForm'),button=document.getElementById('submit'),error=document.getElementById('error'),token=document.getElementById('token');form.addEventListener('submit',async function(event){event.preventDefault();button.setAttribute('aria-busy','true');button.textContent='正在验证…';error.textContent='';try{var response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token.value})});if(!response.ok)throw new Error(await response.text());location.replace('/')}catch(_){error.textContent='Token 不正确，或控制台服务暂时不可用。请检查后重试。';token.select()}finally{button.removeAttribute('aria-busy');button.textContent='进入生命控制台'}});
</script></body></html>"""
